/**
 * Generate the Fibonacci (golden-angle) palette — zero dependencies.
 * Carried from the old @vanduo-oss/core repo, trimmed for vd3: this script
 * now writes ONLY the committed DTCG source; the CSS partials that used to be
 * pushed into the framework repo are generated by scripts/build-tokens.mjs.
 *
 * Design:
 *   - Hue identity stays recognizable (crimson red is crimson, blue is blue) so
 *     existing [data-primary] / [data-neutral] selections keep working, while
 *     the brand hues (primary/secondary) and a dedicated golden accent track are
 *     placed by the GOLDEN ANGLE (~137.5deg) around the wheel — the signature
 *     of the system.
 *   - Every family's 10 shades (0 lightest -> 9 darkest) sit on a per-hue
 *     cusp-anchored phi ramp: lightness decreases monotonically, CHROMA is
 *     scaled by PHI (1.618) and peaks at step round(9 / phi) = 6 (the canonical
 *     "main" shade), and step 6 is anchored so warm/mid hues (orange..sky) stay
 *     vivid rather than olive/brown while maintaining >= 4.5:1 WCAG contrast
 *     against either #ffffff or #1a1d20.
 *   - Colors are computed in OKLCH and converted to sRGB with per-step chroma
 *     clamped into gamut, so every emitted value is a valid in-gamut hex.
 *
 * Output (deterministic):
 *   tokens/primitive/color.fib.tokens.json     committed DTCG source
 */
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const tokensDir = resolve(root, "tokens");

const PHI = 1.618033988749895;
const GOLDEN_ANGLE = 137.50776405003785; // 360 * (1 - 1/phi^2)
const PRIMARY_HUE = 200; // OKLCH hue for the brand "water" primary
const GOLDEN_TRACK = 8; // --vd-golden-1..8 (Fibonacci count)

/** Hue placed by the golden angle, k = 0,1,2,... */
const goldenHue = (k) => (((PRIMARY_HUE + k * GOLDEN_ANGLE) % 360) + 360) % 360;

/**
 * Per-family base hue (OKLCH degrees) + peak chroma. Chromatic families scale
 * base chroma by PHI (1.618) so step 5/6 reaches the vivid sRGB gamut boundary;
 * neutrals carry only a faint tint.
 */
const FAMILIES = {
  // neutrals (near-achromatic)
  gray: { hue: 250, chroma: 0.006, neutral: true },
  slate: { hue: 245, chroma: 0.014, neutral: true },
  charcoal: { hue: 250, chroma: 0.011, neutral: true },
  zinc: { hue: 286, chroma: 0.005, neutral: true },
  neutral: { hue: 0, chroma: 0.0, neutral: true },
  stone: { hue: 70, chroma: 0.008, neutral: true },
  // brand (golden-angle placed)
  primary: { hue: goldenHue(0), chroma: 0.16 * PHI },
  secondary: { hue: goldenHue(1), chroma: 0.16 * PHI },
  // status (conventional, recognizable hues)
  danger: { hue: 20, chroma: 0.16 * PHI },
  error: { hue: 20, chroma: 0.16 * PHI },
  success: { hue: 148, chroma: 0.16 * PHI },
  warning: { hue: 72, chroma: 0.16 * PHI },
  info: { hue: 255, chroma: 0.16 * PHI },
  // named hues (all 17 chromatic customizer hues + grape alias)
  red: { hue: 20, chroma: 0.16 * PHI },
  rose: { hue: 12, chroma: 0.16 * PHI },
  orange: { hue: 48, chroma: 0.16 * PHI },
  amber: { hue: 72, chroma: 0.16 * PHI },
  yellow: { hue: 95, chroma: 0.16 * PHI },
  lime: { hue: 128, chroma: 0.16 * PHI },
  green: { hue: 148, chroma: 0.16 * PHI },
  emerald: { hue: 162, chroma: 0.16 * PHI },
  teal: { hue: 178, chroma: 0.16 * PHI },
  cyan: { hue: 200, chroma: 0.16 * PHI },
  sky: { hue: 225, chroma: 0.16 * PHI },
  blue: { hue: 255, chroma: 0.16 * PHI },
  indigo: { hue: 272, chroma: 0.16 * PHI },
  violet: { hue: 295, chroma: 0.16 * PHI },
  purple: { hue: 322, chroma: 0.16 * PHI },
  grape: { hue: 322, chroma: 0.16 * PHI },
  fuchsia: { hue: 336, chroma: 0.16 * PHI },
  pink: { hue: 352, chroma: 0.16 * PHI },
};

// Base lightness ramp (step 0 -> 9), monotonically decreasing.
const BASE_L_RAMP = [
  0.972, 0.93, 0.872, 0.806, 0.732, 0.66, 0.586, 0.5, 0.41, 0.32,
];
// Neutral scales carry almost zero chroma, so steps 7..9 double as dark-mode
// surfaces and borders without hue-shift clipping; match Open Color's deep
// obsidian dark steps (~0.18 at step 9) while keeping step 5 >= 4.5:1 on dark.
const NEUTRAL_L_RAMP = [
  0.98, 0.948, 0.902, 0.832, 0.725, 0.62, 0.505, 0.39, 0.275, 0.18,
];
// Chroma multiplier per step — peaks at round(9/phi) = 6 (the "main" shade).
const C_RAMP = [0.18, 0.38, 0.62, 0.82, 0.94, 1.0, 1.0, 0.92, 0.78, 0.62];
const MAIN_STEP = Math.round(9 / PHI); // 6

const clamp01 = (x) => (x < 0 ? 0 : x > 1 ? 1 : x);

/** OKLCH -> linear sRGB (Bjorn Ottosson). Returns raw (possibly out-of-gamut). */
const oklchToLinear = (L, C, hDeg) => {
  const h = (hDeg * Math.PI) / 180;
  const a = C * Math.cos(h);
  const b = C * Math.sin(h);
  const l_ = L + 0.3963377774 * a + 0.2158037573 * b;
  const m_ = L - 0.1055613458 * a - 0.0638541728 * b;
  const s_ = L - 0.0894841775 * a - 1.291485548 * b;
  const l = l_ * l_ * l_;
  const m = m_ * m_ * m_;
  const s = s_ * s_ * s_;
  return [
    4.0767416621 * l - 3.3077115913 * m + 0.2309699292 * s,
    -1.2684380046 * l + 2.6097574011 * m - 0.3413193965 * s,
    -0.0041960863 * l - 0.7034186147 * m + 1.707614701 * s,
  ];
};

const EPS = 1e-4;
const inGamut = ([r, g, b]) =>
  r >= -EPS &&
  r <= 1 + EPS &&
  g >= -EPS &&
  g <= 1 + EPS &&
  b >= -EPS &&
  b <= 1 + EPS;

const gamma = (c) =>
  c <= 0.0031308 ? 12.92 * c : 1.055 * Math.pow(c, 1 / 2.4) - 0.055;

const toHex = ([r, g, b]) =>
  "#" +
  [r, g, b]
    .map((c) =>
      Math.round(clamp01(gamma(clamp01(c))) * 255)
        .toString(16)
        .padStart(2, "0"),
    )
    .join("");

/** Largest in-gamut chroma <= C at (L, hue), via binary search; then to hex. */
const oklchToHex = (L, C, hue) => {
  if (inGamut(oklchToLinear(L, C, hue))) return toHex(oklchToLinear(L, C, hue));
  let lo = 0;
  let hi = C;
  for (let i = 0; i < 32; i++) {
    const mid = (lo + hi) / 2;
    if (inGamut(oklchToLinear(L, mid, hue))) lo = mid;
    else hi = mid;
  }
  return toHex(oklchToLinear(L, lo, hue));
};

/** Relative luminance and WCAG contrast ratio for step-6 contrast guard. */
const luminance = (hex) => {
  const n = hex.replace("#", "");
  const ch = [0, 2, 4].map((i) => parseInt(n.slice(i, i + 2), 16) / 255);
  const lin = ch.map((c) =>
    c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4,
  );
  return 0.2126 * lin[0] + 0.7152 * lin[1] + 0.0722 * lin[2];
};

const contrast = (a, b) => {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
};

/**
 * Per-hue cusp-anchored step-6 lightness with WCAG >= 4.5:1 contrast guard
 * against either #ffffff (for deep jewel hues) or #1a1d20 (for warm/mid hues).
 */
const targetL6ForHue = (hDeg, peakC, neutral = false) => {
  if (neutral) return BASE_L_RAMP[MAIN_STEP];
  const h = ((hDeg % 360) + 360) % 360;
  if (h >= 40 && h <= 235) {
    const distFromYellow = Math.min(Math.abs(h - 95), 360 - Math.abs(h - 95));
    const warmLift = Math.max(0, 1 - distFromYellow / 55) * 0.16;
    let L6 = 0.65 + warmLift;
    while (L6 < 0.85 && contrast(oklchToHex(L6, peakC, h), "#1a1d20") < 4.55) {
      L6 += 0.002;
    }
    return L6;
  }
  let L6 = 0.594;
  while (L6 > 0.45 && contrast(oklchToHex(L6, peakC, h), "#ffffff") < 4.55) {
    L6 -= 0.001;
  }
  return L6;
};

const buildRampForL6 = (L6) => {
  const L0 = BASE_L_RAMP[0];
  const L9 = 0.31;
  const base0 = BASE_L_RAMP[0];
  const base6 = BASE_L_RAMP[MAIN_STEP];
  const base9 = BASE_L_RAMP[9];
  return BASE_L_RAMP.map((b, i) => {
    if (i <= MAIN_STEP) {
      const t = (base0 - b) / (base0 - base6);
      return L0 - t * (L0 - L6);
    }
    const t = (base6 - b) / (base6 - base9);
    return L6 - t * (L6 - L9);
  });
};

/** Full 0..9 scale for a family. */
const scaleFor = ({ hue, chroma, neutral }) => {
  const L6 = targetL6ForHue(hue, chroma, Boolean(neutral));
  const ramp = neutral ? NEUTRAL_L_RAMP : buildRampForL6(L6);
  return ramp.map((L, i) => oklchToHex(L, chroma * C_RAMP[i], hue));
};

// ── Build the DTCG tree (mirrors color.tokens.json shape). ──
const colorLeaf = (hex) => ({ $type: "color", $value: hex });
const tree = {
  $description:
    "Primitive palette — Fibonacci (golden-angle) scales. Generated by scripts/generate-fib-palette.mjs; do not edit by hand.",
};
for (const [family, def] of Object.entries(FAMILIES)) {
  const scale = scaleFor(def);
  tree[family] = Object.fromEntries(
    scale.map((hex, i) => [String(i), colorLeaf(hex)]),
  );
}
// Golden accent track: golden-1..N, each the "main" shade of a golden-angle hue.
const golden = {};
for (let k = 0; k < GOLDEN_TRACK; k++) {
  const h = goldenHue(k);
  const peakC = 0.16 * PHI * C_RAMP[MAIN_STEP];
  const L6 = targetL6ForHue(h, peakC, false);
  const hex = oklchToHex(L6, peakC, h);
  golden[String(k + 1)] = colorLeaf(hex);
}
tree.golden = golden;

const fibPath = resolve(tokensDir, "primitive/color.fib.tokens.json");
writeFileSync(fibPath, JSON.stringify(tree, null, 2) + "\n");

console.log(
  `Generated ${Object.keys(FAMILIES).length + 1} families -> tokens/primitive/color.fib.tokens.json`,
);
